INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "care_plans", "sensitive_check", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-000000000bb9', 'ws_one_small_thing', 'One small thing', NULL, 'One tiny thing for a heavy day. Tiny is the point.', false, 'worksheet', 'One tiny thing for a heavy day. Tiny is the point.', NULL, 'do_what_matters', 'Behavioural activation (single-step)', 'one action from six, or their own, then whether it happened. Deliberately single-step and tiny, so it stays possible on the heaviest days.', 'open', 'light', 3, $ws_ws_one_small_thing${"version":1,"intro":"On a heavy day, the list of everything you should be doing can be the heaviest thing of all. Let's shrink it to one small thing — something so small it almost feels too easy.","fields":[{"id":"pick","type":"choice","prompt":"What's one small thing you could do right now?","helper":"Pick whatever feels possible today. Nothing here is too small.","required":true,"options":[{"value":"drink_water","label":"Drink a glass of water"},{"value":"open_window","label":"Open a window"},{"value":"wash_face","label":"Wash my face"},{"value":"step_outside","label":"Step outside for two minutes"},{"value":"message_someone","label":"Message one person"},{"value":"one_song","label":"Put on one song"},{"value":"something_else","label":"Something of my own"}]},{"id":"own_thing","type":"short_text","prompt":"What's your small thing?","helper":"Anything at all. It only has to be doable today.","required":true,"visibleWhen":{"field":"pick","in":["something_else"]}},{"id":"did_it","type":"choice","prompt":"Did it happen?","helper":"Both answers are fine.","options":[{"value":"yes","label":"Did it"},{"value":"no","label":"Not this time"}]}],"closing":{"text":"Either way, you showed up on a heavy day. That isn't nothing."}}$ws_ws_one_small_thing$::jsonb, NULL, 'draft', NULL, 60, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bba', 'ws_mood_activity_log', 'Mood and activity log', NULL, 'Note what you were doing and how it felt, then read the week in your own words.', false, 'worksheet', 'Note what you were doing and how it felt, then read the week in your own words.', NULL, 'energy_life', 'Behavioural activation (activity and mood monitoring)', 'activity and mood monitored together, one entry per save. The week reads back grouped by the activity words the client used, with the feelings they picked — no score, no average, no ranking of feelings.', 'open', 'light', 5, $ws_ws_mood_activity_log${"version":1,"intro":"How you feel and what you're doing are more connected than they look. Log a few moments across the week, and you can read back which things tended to come with which feelings.","fields":[{"id":"when","type":"datetime","prompt":"When was this?","withDate":true,"withTime":true,"required":true},{"id":"doing","type":"short_text","prompt":"What were you doing?","helper":"A few words is plenty — \"chai with a friend\", \"walk after dinner\", \"scrolling in bed\".","required":true},{"id":"feelings","type":"feelings_picker","prompt":"How did you feel?","helper":"Pick up to three.","required":true,"feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}],"maxSelections":3},{"id":"noticed","type":"closing_reflection","prompt":"Anything you notice, looking back over the week?","helper":"There's no right answer. This is just for you."}],"closing":{"text":"Each entry is one moment. It is not a verdict on the week."},"review":{"withinDays":7,"activityField":"doing","feelingsField":"feelings"}}$ws_ws_mood_activity_log$::jsonb, NULL, 'draft', NULL, 60, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bbb', 'ws_strengths', 'Strengths spotting', NULL, 'Notice what you''re already good at, and one time you used it.', false, 'worksheet', 'Notice what you''re already good at, and one time you used it.', NULL, 'be_kinder', 'Strengths identification', 'ticks only, then one concrete recent example, so a strength lands as evidence rather than a compliment. Light on purpose.', 'open', 'light', 5, $ws_ws_strengths${"version":1,"intro":"Low mood makes strengths hard to see. They stop feeling like strengths and start feeling like nothing special. They are still there. This is a few minutes of looking properly.","fields":[{"id":"strengths","type":"checklist","prompt":"Which of these are true of you, at least some of the time?","helper":"Tick as many as fit. This isn't boasting — it's just true.","minSelections":1,"options":[{"value":"kind","label":"Kind"},{"value":"loyal","label":"Loyal"},{"value":"funny","label":"Funny"},{"value":"good_listener","label":"A good listener"},{"value":"curious","label":"Curious"},{"value":"patient","label":"Patient"},{"value":"honest","label":"Honest"},{"value":"creative","label":"Creative"},{"value":"determined","label":"Determined"},{"value":"thoughtful","label":"Thoughtful"},{"value":"practical","label":"Practical"},{"value":"brave","label":"Brave"}]},{"id":"recent","type":"short_text","prompt":"One time recently you used one of them","helper":"Even a small time counts — holding a door, remembering something, saying no.","required":true}],"closing":{"text":"You didn't have to become someone else to have these. They were already yours."}}$ws_ws_strengths$::jsonb, NULL, 'draft', NULL, 30, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bbc', 'ws_things_i_might_enjoy', 'Things I might enjoy', NULL, 'Everyday things worth trying, and a way to carry the ones you pick into your planner.', false, 'worksheet', 'Everyday things worth trying, and a way to carry the ones you pick into your planner.', NULL, 'do_what_matters', 'Behavioural activation (activity menu)', 'a menu to lower the cost of choosing an activity. Picked ideas are carried into the client-wide Small things planner; the planner itself is untouched.', 'open', 'light', 5, $ws_ws_things_i_might_enjoy${"version":1,"intro":"When you've felt low for a while, it's easy to forget what you actually enjoy, or to believe nothing would help anyway. Here are some ordinary things. Tick anything that sounds even slightly possible.","fields":[{"id":"ideas","type":"checklist","prompt":"Which of these might be worth a try?","helper":"Nothing here is a rule, and nothing has to be done today.","minSelections":1,"options":[{"value":"chai_with_friend","label":"Chai with a friend"},{"value":"walk","label":"A walk, anywhere"},{"value":"cook_something","label":"Cooking something simple"},{"value":"game","label":"A game — phone, board or cards"},{"value":"music","label":"Music, loud or quiet"},{"value":"call_cousin","label":"Calling a cousin"},{"value":"street_food","label":"Street food you like"},{"value":"cycle","label":"A cycle ride"},{"value":"cricket","label":"Cricket, watching or playing"},{"value":"terrace_sunset","label":"Sitting on the terrace at sunset"},{"value":"drawing","label":"Drawing or doodling"},{"value":"film_with_someone","label":"A film with someone"}]}],"closing":{"text":"Picking is the easy half. When you're ready, the planner is somewhere to put the ones you chose.","handOff":{"toolId":"ws_small_things","field":"ideas","label":"Take these to my Small things planner","targetField":"plan","targetColumn":"what"}}}$ws_ws_things_i_might_enjoy$::jsonb, NULL, 'draft', NULL, 100, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bbd', 'ws_tiny_steps', 'Tiny steps ladder', NULL, 'Turn one big thing into steps, from the smallest to the biggest.', false, 'worksheet', 'Turn one big thing into steps, from the smallest to the biggest.', NULL, 'do_what_matters', 'Task decomposition', 'task breakdown with the first step scheduled. Smallest first, so the ladder is a way in rather than a to-do list.', 'assigned', 'light', 10, $ws_ws_tiny_steps${"version":1,"intro":"A big task stays impossible while it's still one big task. Broken into steps, the first one is usually something you could do today.","fields":[{"id":"problem","type":"short_text","prompt":"What's the thing you've been putting off?","helper":"One line. It doesn't have to be worded well.","required":true},{"id":"steps","type":"row_list","prompt":"What are the steps, smallest first?","helper":"Start with something almost too easy. The last one can be big — you won't be doing it today.","maxRows":8,"addLabel":"Add another step","columns":[{"id":"step","label":"Step","type":"text"}]},{"id":"first_step_on","type":"datetime","prompt":"When will you do the first one?","helper":"A day is enough. If it slips, it slips — you can change it.","withDate":true,"withTime":false},{"id":"noticed","type":"closing_reflection","prompt":"Which step feels most doable right now?"}],"closing":{"text":"You don't have to climb it today. You just have to know where the first step is."}}$ws_ws_tiny_steps$::jsonb, NULL, 'draft', NULL, 110, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bbe', 'ws_inner_critic', 'Meet the inner critic', NULL, 'Get to know the critical voice — what it says, and what you''d say back.', false, 'worksheet', 'Get to know the critical voice — what it says, and what you''d say back.', NULL, 'be_kinder', 'Cognitive defusion (externalising the inner critic)', 'externalises the critical voice so it reads as one voice rather than the truth. High load: it asks the client to write the critic out in full, which can be upsetting. Carry the deeper safety screen.', 'assigned', 'demanding', 15, $ws_ws_inner_critic${"version":1,"intro":"Most people have a voice inside that is harsher than they would ever be to a friend. This is a place to describe it properly, as something separate from you, with its own habits.","fields":[{"id":"name","type":"short_text","prompt":"If this voice had a name, what would it be?","helper":"Something silly is fine. A name makes it easier to hear as one voice rather than the truth.","required":true},{"id":"says","type":"long_text","prompt":"What does it usually say?","helper":"Write it the way it actually speaks, as harsh as it is. Nothing here is edited or softened.","required":true},{"id":"loudest","type":"short_text","prompt":"When is it loudest?","helper":"A time of day, a situation, a kind of person. Anything you have noticed."},{"id":"protecting","type":"short_text","prompt":"What might it be trying to protect you from?","helper":"Critics often started as protection. There's no right answer here."},{"id":"back","type":"short_text","prompt":"What would you like to say back to it?","helper":"In your own words. It doesn't have to be kind — it just has to be yours."}],"closing":{"text":"You named it, so it's a voice now, not the truth about you."}}$ws_ws_inner_critic$::jsonb, NULL, 'draft', NULL, 40, NULL, ARRAY['low_mood']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bbf', 'ws_reconnect_planner', 'Reconnect planner', NULL, 'Pick someone you miss, choose how to reach out, and set a day.', false, 'worksheet', 'Pick someone you miss, choose how to reach out, and set a day.', NULL, 'people_boundaries', 'Behavioural activation (social reconnection)', 'one person, one channel, one date. Kept to a single reach-out so it does not become a list of everyone they have lost touch with.', 'assigned', 'light', 10, $ws_ws_reconnect_planner${"version":1,"intro":"When you've been low, people can drift without anyone deciding to. Picking one person and one small way to reach out is easier than trying to fix everything at once.","fields":[{"id":"people","type":"row_list","prompt":"Who do you miss?","helper":"One name per line. No need to say why.","maxRows":8,"addLabel":"Add someone","columns":[{"id":"who","label":"Who","type":"text"}]},{"id":"how","type":"choice","prompt":"How would you like to reach out?","helper":"The smallest one that feels possible is the right one.","options":[{"value":"message","label":"A message"},{"value":"meme","label":"Send a meme"},{"value":"call","label":"A call"},{"value":"meet","label":"Meet up"}]},{"id":"when","type":"datetime","prompt":"When?","withDate":true,"withTime":false},{"id":"did_it","type":"choice","prompt":"How did it go?","helper":"Not yet is fine. It stays here for whenever you're ready.","options":[{"value":"yes","label":"Did it"},{"value":"no","label":"Not yet"}]}],"closing":{"text":"Reaching out once doesn't undo the distance. It's still a start."}}$ws_ws_reconnect_planner$::jsonb, NULL, 'draft', NULL, 50, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bc0', 'ws_comparison_check', 'Comparison check', NULL, 'Look at where comparison happens, what it leaves out, and one small thing to do now.', false, 'worksheet', 'Look at where comparison happens, what it leaves out, and one small thing to do now.', NULL, 'untangle_thoughts', 'Cognitive restructuring (social comparison)', 'where, what feeling it left, what was compared to, and what the post leaves out. High load: comparison is often where body and eating material surfaces, so it carries the deeper safety screen. No weight, body or food fields anywhere.', 'assigned', 'demanding', 10, $ws_ws_comparison_check${"version":1,"intro":"Comparing yourself to other people is close to automatic, and phones make it constant. This is a few minutes of looking at it closely, without deciding you should stop feeling it.","fields":[{"id":"where","type":"choice","prompt":"Where were you when it happened?","required":true,"options":[{"value":"instagram","label":"Instagram"},{"value":"youtube","label":"YouTube"},{"value":"college","label":"College"},{"value":"family","label":"Family"},{"value":"other","label":"Somewhere else"}]},{"id":"feelings","type":"feelings_picker","prompt":"How did it leave you feeling?","helper":"Pick up to three.","required":true,"feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}],"maxSelections":3},{"id":"comparing_to","type":"short_text","prompt":"What were you comparing yourself to?","helper":"A post, a person, a way someone's life looked.","required":true},{"id":"not_shown","type":"short_text","prompt":"What doesn't that post or person show?","helper":"Everyone's day has parts nobody photographs."},{"id":"do_now","type":"short_text","prompt":"One small thing you'll do now","helper":"Something for you, not for how it looks. Closing the app counts."}],"closing":{"text":"You saw it clearly for a minute. That's the skill, and it gets easier with practice."}}$ws_ws_comparison_check$::jsonb, NULL, 'draft', NULL, 100, NULL, ARRAY['low_mood']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000bc1', 'ws_miracle_question', 'The morning after a miracle', NULL, 'Imagine things had changed overnight, and find the first small step.', false, 'worksheet', 'Imagine things had changed overnight, and find the first small step.', NULL, 'do_what_matters', 'Solution-focused (miracle question)', 'the miracle question, kept concrete: what they would notice, where they are now, one step up. The 0-10 is the client''s own number, never read as a band.', 'assigned', 'light', 10, $ws_ws_miracle_question${"version":1,"intro":"This is an old question and it still works. Imagine you go to sleep tonight and, while you sleep, the problem gets easier — not solved, just easier. You wake up and nobody has explained anything to you.","fields":[{"id":"notice","type":"long_text","prompt":"What would you notice first, before anyone told you anything?","helper":"Small and ordinary is good — what you'd see, who you'd speak to, what you'd do differently.","required":true},{"id":"now","type":"scale_0_10","prompt":"Where are you now, on the way to that morning?","minLabel":"0 = nowhere near it","maxLabel":"10 = almost there"},{"id":"step_up","type":"short_text","prompt":"What would one step up from here look like?","helper":"One step. Not the whole way."}],"closing":{"text":"You don't need the whole picture. One step you can actually see is enough to move."}}$ws_ws_miracle_question$::jsonb, NULL, 'draft', NULL, 120, NULL, ARRAY['low_mood']::TEXT[], false, CURRENT_TIMESTAMP)
